// @vitest-environment node
// Frontend schemas vs the backend's OpenAPI document (AGENTS §21).
// `openapi.json` is generated by the backend; its own test fails when the
// snapshot is stale (backend/tests/test_openapi_contract.py), so together
// the two tests catch drift on either side.
import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'
import { z } from 'zod'
import * as auth from './auth'
import * as credentials from './credentials'
