// -- the OpenAPI document ----------------------------------------------------

interface JsonSchema {
    $ref?: string | undefined
    anyOf?: JsonSchema[] | undefined
    oneOf?: JsonSchema[] | undefined
    type?: string | string[] | undefined
    enum?: unknown[] | undefined
    const?: unknown
    format?: string | undefined
    properties?: Record<string, JsonSchema> | undefined
    required?: string[] | undefined
    items?: JsonSchema | undefined
}
const jsonSchema: z.ZodType<JsonSchema> = z.lazy(() =>
    z.object({
        $ref: z.string().optional(),
        anyOf: z.array(jsonSchema).optional(),
        oneOf: z.array(jsonSchema).optional(),
        type: z.union([z.string(), z.array(z.string())]).optional(),
        enum: z.array(z.unknown()).optional(),
        const: z.unknown().optional(),
        format: z.string().optional(),
        properties: z.record(z.string(), jsonSchema).optional(),
        required: z.array(z.string()).optional(),
        items: jsonSchema.optional(),
    }),
)
const jsonBody = z.object({
    content: z
        .object({
            'application/json': z.object({ schema: jsonSchema }).optional(),
            'application/zip': z.object({}).optional(),
        })
        .optional(),
})
const documentSchema = z.object({
    paths: z.record(
        z.string(),
        z.record(
            z.string(),
            z.object({
                requestBody: jsonBody.optional(),
                responses: z.record(z.string(), jsonBody),
            }),
        ),
    ),
    components: z.object({ schemas: z.record(z.string(), jsonSchema) }),
})
const document = documentSchema.parse(
    JSON.parse(
        readFileSync(new URL('./openapi.json', import.meta.url), 'utf8'),
    ),
)

// -- normalization: both sides reduced to what the wire format promises ------

interface Shape {
    type: string // 'object', 'array', 'union', 'string:date-time', 'enum(a,b)', ...
    props?: Record<string, { required: boolean; shape: Shape }>
    items?: Shape
    members?: Shape[]
}

function resolve(ref: string): JsonSchema {
    // Zod's own definitions: only z.json() is recursive, and any JSON value
    // is what Pydantic's JsonValue (no type) says too.
    if (ref.startsWith('#/$defs/')) return {}
    const name = ref.replace('#/components/schemas/', '')
    const target = document.components.schemas[name]
    if (!target) throw new Error(`unresolvable $ref ${ref}`)
    return target
}

function normalize(schema: JsonSchema): Shape {
    if (schema.$ref) return normalize(resolve(schema.$ref))
    // Pydantic writes nullables as anyOf, Zod as a type array: same union.
    const variants =
        schema.anyOf ??
        schema.oneOf ??
        (Array.isArray(schema.type)
            ? schema.type.map((type) => ({ ...schema, type }))
            : undefined)
    if (variants) {
        const members = variants.map(normalize).flatMap((s) => s.members ?? [s])
        // ponytail: members are matched by sort order, so two object members
        // differing only in optionality may pair up wrongly; fine until unions of objects appear.
        members.sort((a, b) =>
            JSON.stringify(a).localeCompare(JSON.stringify(b)),
        )
        return members.length === 1 && members[0]
            ? members[0]
            : { type: 'union', members }
    }
    if (schema.enum)
        return { type: `enum(${schema.enum.map(String).sort().join(',')})` }
    if ('const' in schema) return { type: `enum(${String(schema.const)})` }
    if (schema.type === 'object' && schema.properties) {
        const required = new Set(schema.required ?? [])
        const props: NonNullable<Shape['props']> = {}
        for (const [name, prop] of Object.entries(schema.properties)) {
            props[name] = {
                required: required.has(name),
                shape: normalize(prop),
            }
        }
        return { type: 'object', props }
    }
    if (schema.type === 'object') return { type: 'record' }
    if (schema.type === 'array')
        return { type: 'array', items: normalize(schema.items ?? {}) }
    // Type arrays were turned into unions above; no type means any value.
    if (typeof schema.type !== 'string') return { type: 'unknown' }
    return {
        type: schema.format ? `${schema.type}:${schema.format}` : schema.type,
    }
}

function fromZod(schema: z.ZodType): Shape {
    // 'input': what the frontend schema accepts, which is what must cover the wire.
    return normalize(jsonSchema.parse(z.toJSONSchema(schema, { io: 'input' })))
}

/**
 * Differences that would make valid backend responses fail (or pass
 * unchecked) in the frontend. Exact field sets: a new backend field must be
 * a deliberate frontend change, not silently ignored.
 */
function compare(front: Shape, back: Shape, at = '$'): string[] {
    if (front.type !== back.type)
        return [`${at}: frontend ${front.type}, backend ${back.type}`]
    const issues: string[] = []
    if (front.items && back.items)
        issues.push(...compare(front.items, back.items, `${at}[]`))
    if (front.members && back.members) {
        if (front.members.length !== back.members.length)
            issues.push(`${at}: union members differ`)
        front.members.forEach((m, i) => {
            const other = back.members?.[i]
            if (other) issues.push(...compare(m, other, `${at}|${String(i)}`))
        })
    }
    const names = new Set([
        ...Object.keys(front.props ?? {}),
        ...Object.keys(back.props ?? {}),
    ])
    for (const name of [...names].sort()) {
        const f = front.props?.[name]
        const b = back.props?.[name]
        const path = `${at}.${name}`
        if (!f) issues.push(`${path}: missing in frontend schema`)
        else if (!b) issues.push(`${path}: not in backend contract`)
        else {
            if (f.required && !b.required)
                issues.push(
                    `${path}: required in frontend, optional in backend`,
                )
            issues.push(...compare(f.shape, b.shape, path))
        }
    }
    return issues
}

// -- what the services actually send -----------------------------------------

interface Call {
    method: HttpMethod
    path: string
    schema: z.ZodType
    body: unknown
    /** A download: the bytes are the response, not JSON. */
    binary?: boolean
}

/** Records each request instead of sending it (`request` delegates here). */
class RecordingClient extends ApiClient {
    readonly calls: Call[] = []
    override requestWithBody<S extends z.ZodType>(
        method: HttpMethod,
        path: string,
        schema: S,
        options: RequestOptions = {},
    ): Promise<{ data: z.output<S>; body: string }> {
        this.calls.push({ method, path, schema, body: options.body })
        return new Promise<never>(() => undefined)
    }
    override download(
        method: HttpMethod,
        path: string,
        options: RequestOptions = {},
    ): Promise<Blob> {
        this.calls.push({
            method,
            path,
            schema: z.undefined(),
            body: options.body,
            binary: true,
        })
        return new Promise<never>(() => undefined)
    }
}

