const serviceFunctions = modules.flatMap((module) =>
    Object.values(module).filter((v) => typeof v === 'function'),
)

function operation(method: HttpMethod, path: string) {
    const full = `${DEFAULT_BASE_URL}${path}`
    const exact = document.paths[full]
    const templated = Object.entries(document.paths).find(([template]) =>
        new RegExp(`^${template.replace(/\{[^}]+\}/g, '[^/]+')}$`).test(full),
    )?.[1]
    return (exact ?? templated)?.[method.toLowerCase()]
}

// -- tests ---------------------------------------------------------------------

describe('frontend schemas match the backend OpenAPI contract', () => {
    it('every service function is covered', () => {
        expect(recorder.calls).toHaveLength(serviceFunctions.length)
    })

    it.each(recorder.calls.map((c) => [`${c.method} ${c.path}`, c] as const))(
        '%s',
        (_name, call) => {
            const op = operation(call.method, call.path)
            if (!op)
                throw new Error(
                    `${call.method} ${DEFAULT_BASE_URL}${call.path} is not in the contract`,
                )

            const success = Object.keys(op.responses)
                .filter((status) => status.startsWith('2'))
                .sort()[0]
            expect(success, 'documented success response').toBeDefined()
            const content = op.responses[success ?? '']?.content ?? {}
            if (call.binary) {
                expect(Object.keys(content)).toEqual(['application/zip'])
                expect(call.body).toBeUndefined()
                return
            }
            const responseSchema =
                op.responses[success ?? '']?.content?.['application/json']
                    ?.schema
            if (responseSchema) {
                expect(
                    compare(fromZod(call.schema), normalize(responseSchema)),
                ).toEqual([])
            } else {
                expect(
                    call.schema.safeParse(undefined).success,
                    'no-content response accepts an empty body',
                ).toBe(true)
            }

            const requestSchema =
                op.requestBody?.content?.['application/json']?.schema
            if (!requestSchema) {
                expect(call.body).toBeUndefined()
                return
            }
            const sent = Object.keys(
                z.record(z.string(), z.unknown()).parse(call.body),
            )
            // An optional body is `X | null`; compare against X.
            const request = normalize(requestSchema)
            const body =
                request.members?.find((m) => m.type !== 'null') ?? request
            // A free-form JSON object (execution input) accepts any field.
            if (body.type === 'record') return
            const props = body.props ?? {}
            expect(
                sent.filter((k) => !(k in props)),
                'fields the backend does not accept',
            ).toEqual([])
            expect(
                Object.keys(props).filter(
                    (k) => props[k]?.required && !sent.includes(k),
                ),
                'required fields not sent',
            ).toEqual([])
        },
    )

    it('the error envelope matches ErrorResponse', () => {
        expect(
            compare(
                fromZod(errorEnvelopeSchema),
                normalize({ $ref: '#/components/schemas/ErrorResponse' }),
            ),
        ).toEqual([])
    })
})

describe('the comparison itself', () => {
    const back = normalize({
        type: 'object',
        properties: {
            id: { type: 'string' },
            at: {
                anyOf: [
                    { type: 'string', format: 'date-time' },
                    { type: 'null' },
                ],
            },
            note: { type: 'string' },
        },
        required: ['id', 'at'],
    })
    const front = (shape: z.ZodRawShape) => fromZod(z.object(shape))

    it('accepts an equivalent schema', () => {
        expect(
            compare(
                front({
                    id: z.string(),
                    at: z.iso.datetime().nullable(),
                    note: z.string().optional(),
                }),
                back,
            ),
        ).toEqual([])
    })

    it('reports missing, extra, mistyped and too-strict fields', () => {
        expect(
            compare(
                front({
                    id: z.number(),
                    at: z.iso.datetime(),
                    note: z.string(),
                    extra: z.string(),
                }),
                back,
            ),
        ).toEqual([
            '$.at: frontend string:date-time, backend union',
            '$.extra: not in backend contract',
            '$.id: frontend number, backend string',
            '$.note: required in frontend, optional in backend',
        ])
        expect(
            compare(
                front({ id: z.string(), at: z.iso.datetime().nullable() }),
                back,
            ),
        ).toEqual(['$.note: missing in frontend schema'])
    })
})

